<?php
require 'config.php';require 'includes/header.php';$baixo=$pdo->query('SELECT p.*,c.nome categoria FROM produtos p JOIN categorias c ON c.id=p.categoria_id WHERE p.estoque<=p.estoque_minimo ORDER BY p.estoque ASC')->fetchAll();$vencidos=$pdo->query('SELECT p.*,c.nome categoria FROM produtos p JOIN categorias c ON c.id=p.categoria_id WHERE p.validade IS NOT NULL AND p.validade<CURDATE() ORDER BY p.validade')->fetchAll();$vencer=$pdo->query('SELECT p.*,c.nome categoria FROM produtos p JOIN categorias c ON c.id=p.categoria_id WHERE p.validade BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 30 DAY) ORDER BY p.validade')->fetchAll();
?>
<div class="eyebrow">Controle operacional</div><h1 class="titulo">Estoque e validade</h1><p class="subtitulo">Acompanhe produtos que precisam de reposição ou atenção com a data de validade.</p>
<div class="secao"><h2>Estoque baixo <span class="badge baixo"><?=count($baixo)?></span></h2></div><div class="painel"><table class="tabela"><thead><tr><th>Produto</th><th>Categoria</th><th>Estoque atual</th><th>Estoque mínimo</th><th>Ação</th></tr></thead><tbody><?php foreach($baixo as $p): ?><tr><td><?=e($p['nome'])?></td><td><?=e($p['categoria'])?></td><td><span class="badge baixo"><?=$p['estoque']?></span></td><td><?=$p['estoque_minimo']?></td><td><a class="btn small" href="produto_form.php?id=<?=$p['id']?>">Atualizar</a></td></tr><?php endforeach ?><?php if(!$baixo): ?><tr><td colspan="5" class="vazio">Nenhum produto com estoque baixo.</td></tr><?php endif ?></tbody></table></div>
<div class="secao"><h2>Produtos vencidos <span class="badge vencido"><?=count($vencidos)?></span></h2></div><div class="painel"><table class="tabela"><thead><tr><th>Produto</th><th>Validade</th><th>Estoque</th><th>Ação</th></tr></thead><tbody><?php foreach($vencidos as $p): ?><tr><td><?=e($p['nome'])?></td><td><?=date('d/m/Y',strtotime($p['validade']))?></td><td><?=$p['estoque']?></td><td><a class="btn small sec" href="produto_detalhe.php?id=<?=$p['id']?>">Detalhes</a></td></tr><?php endforeach ?><?php if(!$vencidos): ?><tr><td colspan="4" class="vazio">Nenhum produto vencido.</td></tr><?php endif ?></tbody></table></div>
<div class="secao"><h2>Validade nos próximos 30 dias <span class="badge baixo"><?=count($vencer)?></span></h2></div><div class="painel"><table class="tabela"><thead><tr><th>Produto</th><th>Validade</th><th>Estoque</th></tr></thead><tbody><?php foreach($vencer as $p): ?><tr><td><?=e($p['nome'])?></td><td><?=date('d/m/Y',strtotime($p['validade']))?></td><td><?=$p['estoque']?></td></tr><?php endforeach ?><?php if(!$vencer): ?><tr><td colspan="3" class="vazio">Nenhum produto próximo do vencimento.</td></tr><?php endif ?></tbody></table></div>
<?php require 'includes/footer.php'; ?>
